/// <summary>
/// Extension class for the LedgerJournalTable form.
/// </summary>
/// Added for CFR41 Bulk AP Invoice approval and cross pillar journal.
[ExtensionOf(formStr(LedgerJournalTable))]
final class METLedgerJournalTableForm_Extension
{
}

Method.Source:
/// <summary>
/// Initializes form controls based on the journal type.
/// </summary>
/// <param name="_journalTypeId">
/// The journal type ID
/// </param>
protected void initControls(Integer _journalTypeId)
{
    next initControls(_journalTypeId);

    LedgerJournalType ledgerJournalType = any2Enum(_journalTypeId);

    if (ledgerJournalType == LedgerJournalType::Daily)
    {
        this.design().controlName("METDownloadTemplateExcel").visible(true);
    }
}

/// <summary>
/// Filter the workflow based on caller menu.
/// </summary>
public void init()
{
    next init();

}
